-- ============================================================
-- 圣遗物一览补齐：46 套五星 / 15 套四星 / 3 套三星
-- 幂等：INSERT ... ON DUPLICATE KEY UPDATE，可重复执行
-- ============================================================

ON DUPLICATE KEY UPDATE name=VALUES(name),rarity=VALUES(rarity),element=VALUES(element),region=VALUES(region),two_piece=VALUES(two_piece),four_piece=VALUES(four_piece),flavor=VALUES(flavor),image=VALUES(image),theme_color=VALUES(theme_color),sort_order=VALUES(sort_order),status=VALUES(status);
